package daily;

public class evenandodd_assignment {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int num=225;
		int a=num%2;
	
	if(a==0)
	{
		System.out.println("The number" + num + "is even");
	}
	else 
	{
		System.out.println("The number"  + num + "is odd");
	}
			
	}

}
